import assert from "node:assert/strict"

const SERVER_URL = process.env.TERMINUSDB_URL || "http://localhost:6363"
const AUTH_USER = process.env.TERMINUSDB_USER || "admin"
const AUTH_KEY = process.env.TERMINUSDB_KEY || "root"
const DB_NAME = "star-wars"
const DB_PATH = `${AUTH_USER}/${DB_NAME}`
const AUTH_HEADER = "Basic " + Buffer.from(`${AUTH_USER}:${AUTH_KEY}`).toString("base64")
const REMOTE_AUTH = "Basic " + Buffer.from("public:public").toString("base64")

// ============================================================================
// Helpers
// ============================================================================

async function apiCall(method, path, body, extraHeaders = {}) {
  const url = `${SERVER_URL}${path}`
  const headers = {
    "Authorization": AUTH_HEADER,
    "Content-Type": "application/json",
    ...extraHeaders,
  }
  const options = { method, headers }
  if (body !== undefined && body !== null) {
    options.body = typeof body === "string" ? body : JSON.stringify(body)
  }
  const response = await fetch(url, options)
  const text = await response.text()
  let json = null
  try { json = JSON.parse(text) } catch { /* not JSON */ }
  return { status: response.status, body: json, text }
}

async function graphqlQuery(query) {
  return apiCall("POST", "/api/graphql/admin/star-wars", { query })
}

async function isServerReachable() {
  try {
    const res = await fetch(`${SERVER_URL}/api/info`, { headers: { Authorization: AUTH_HEADER } })
    return res.status === 200
  } catch {
    return false
  }
}

async function isRemoteReachable() {
  try {
    const res = await fetch("https://data.terminusdb.org/api/info", { signal: AbortSignal.timeout(5000) })
    return res.status === 200
  } catch {
    return false
  }
}

async function deleteDb(name) {
  for (let attempt = 0; attempt < 5; attempt++) {
    try {
      const res = await apiCall("DELETE", `/api/db/${AUTH_USER}/${name}`)
      if (res.status === 200 || res.status === 404) return
      if (res.text && res.text.includes("NotFinalized")) {
        await new Promise(r => setTimeout(r, 2000))
        continue
      }
      return
    } catch {
      await new Promise(r => setTimeout(r, 1000))
    }
  }
}

async function waitForDb(name, maxWait = 60000) {
  const start = Date.now()
  while (Date.now() - start < maxWait) {
    try {
      const res = await apiCall("GET", `/api/document/${AUTH_USER}/${name}/local/branch/main?count=1&as_list=true`)
      if (res.status === 200) return true
      if (res.text && res.text.includes("NotFinalized")) {
        await new Promise(r => setTimeout(r, 1000))
        continue
      }
      return res.status !== 404
    } catch {
      await new Promise(r => setTimeout(r, 1000))
    }
  }
  return false
}

async function deleteBranch(branchPath) {
  try {
    await apiCall("DELETE", `/api/branch/${branchPath}`)
  } catch { /* ignore errors during cleanup */ }
}

async function ensureDbExists() {
  const check = await apiCall("GET", `/api/document/${DB_PATH}/local/branch/main?count=1&as_list=true`)
  if (check.status === 200) return true

  const remoteOk = await isRemoteReachable()
  if (!remoteOk) return false

  await deleteDb(DB_NAME)
  const cloneRes = await apiCall("POST", `/api/clone/${DB_PATH}`,
    { "remote_url": "https://data.terminusdb.org/public/star-wars", "label": "star-wars", "comment": "Cloned for test" },
    { "Authorization-Remote": REMOTE_AUTH }
  )
  if (cloneRes.status < 200 || cloneRes.status >= 300) return false
  return await waitForDb(DB_NAME, 90000)
}

// ============================================================================
// Tests — Exact code blocks from page.md
// ============================================================================

describe("graphql-basics — page code blocks", function () {
  let serverOk = false

  before(async function () {
    this.timeout(120000)
    serverOk = await isServerReachable()
    if (!serverOk) return this.skip()

    const dbReady = await ensureDbExists()
    if (!dbReady) return this.skip()
  })

  // -------------------------------------------------------------------------
  // Block 1 — GraphQL query: get all People with label field
  // -------------------------------------------------------------------------

  it("Block 1: GraphQL query: get all People with label field", async function () {
    const query = `query{
   People{
      label
   }
}`
    const res = await graphqlQuery(query)

    assert.equal(res.status, 200, `GraphQL request failed: ${res.status} ${res.text}`)
    assert.ok(res.body, "Response body should not be null")
    assert.ok(res.body.data, "Response should have data field")
    assert.ok(!res.body.errors, `GraphQL errors: ${JSON.stringify(res.body.errors)}`)
    const results = res.body.data.People
    assert.ok(Array.isArray(results), "People should be an array")
    assert.ok(results.length > 0, "People array should not be empty")
    assert.ok(results[0].label !== undefined, "Each result should have 'label' field")

  })

  // -------------------------------------------------------------------------
  // Block 2 — GraphQL query: get first 5 People with label
  // -------------------------------------------------------------------------

  it("Block 2: GraphQL query: get first 5 People with label", async function () {
    const query = `query{
   People(limit: 5){
      label
   }
}`
    const res = await graphqlQuery(query)

    assert.equal(res.status, 200, `GraphQL request failed: ${res.status} ${res.text}`)
    assert.ok(res.body, "Response body should not be null")
    assert.ok(res.body.data, "Response should have data field")
    assert.ok(!res.body.errors, `GraphQL errors: ${JSON.stringify(res.body.errors)}`)
    const results = res.body.data.People
    assert.ok(Array.isArray(results), "People should be an array")
    assert.equal(results.length, 5, "Should return exactly 5 results")
    const labels = results.map(r => r.label)
    assert.ok(labels.includes("Luke Skywalker"), "Results should include Luke Skywalker")
    assert.ok(labels.includes("Anakin Skywalker"), "Results should include Anakin Skywalker")
    assert.ok(labels.includes("Obi-Wan Kenobi"), "Results should include Obi-Wan Kenobi")
    assert.ok(labels.includes("Wilhuff Tarkin"), "Results should include Wilhuff Tarkin")
    assert.ok(labels.includes("Chewbacca"), "Results should include Chewbacca")

  })

  // -------------------------------------------------------------------------
  // Block 5 — GraphQL query: People(limit: 2) with nested homeworld { label }
  // -------------------------------------------------------------------------

  it("Block 5: GraphQL query: People(limit: 2) with nested homeworld { label }", async function () {
    const query = `query{
   People(limit: 2){
      label
      homeworld{
        label
      }
   }
}`
    const res = await graphqlQuery(query)

    assert.equal(res.status, 200, `GraphQL request failed: ${res.status} ${res.text}`)
    assert.ok(res.body, "Response body should not be null")
    assert.ok(res.body.data, "Response should have data field")
    assert.ok(!res.body.errors, `GraphQL errors: ${JSON.stringify(res.body.errors)}`)
    const results = res.body.data.People
    assert.ok(Array.isArray(results), "People should be an array")
    assert.equal(results.length, 2, "Should return exactly 2 results")
    const labels = results.map(r => r.label)
    assert.ok(labels.includes("Luke Skywalker"), "Results should include Luke Skywalker")
    assert.ok(labels.includes("Obi-Wan Kenobi"), "Results should include Obi-Wan Kenobi")
    assert.ok(results[0].homeworld, "Results should include homeworld")
    assert.ok(results[0].homeworld.label, "Homeworld should have label field")
    const homeworlds = results.map(r => r.homeworld?.label)
    assert.ok(homeworlds.includes("Tatooine"), "Should include Tatooine as homeworld")

  })

  // -------------------------------------------------------------------------
  // Block 7 — GraphQL query: People(limit: 2, offset: 2) with homeworld
  // -------------------------------------------------------------------------

  it("Block 7: GraphQL query: People(limit: 2, offset: 2) with homeworld", async function () {
    const query = `query{
   People(limit: 2, offset:2){
      label
      homeworld{
        label
      }
   }
}`
    const res = await graphqlQuery(query)

    assert.equal(res.status, 200, `GraphQL request failed: ${res.status} ${res.text}`)
    assert.ok(res.body, "Response body should not be null")
    assert.ok(res.body.data, "Response should have data field")
    assert.ok(!res.body.errors, `GraphQL errors: ${JSON.stringify(res.body.errors)}`)
    const results = res.body.data.People
    assert.ok(Array.isArray(results), "People should be an array")
    assert.equal(results.length, 2, "Should return exactly 2 results")
    const labels = results.map(r => r.label)
    assert.ok(labels.includes("Anakin Skywalker"), "Results should include Anakin Skywalker")
    assert.ok(labels.includes("Wilhuff Tarkin"), "Results should include Wilhuff Tarkin")
    assert.ok(results[0].homeworld, "Results should include homeworld")
    assert.ok(results[0].homeworld.label, "Homeworld should have label field")
    const homeworlds = results.map(r => r.homeworld?.label)
    assert.ok(homeworlds.includes("Tatooine"), "Should include Tatooine as homeworld")

  })

})
